      borderBottom: `2px solid ${value ? T.accent : T.line}`,
      fontSize: 19,
      fontWeight: 800,
      letterSpacing: 0.5,
      color: T.ink,
      fontVariantNumeric: "tabular-nums",
      textAlign: "center",
      transition: "border-color 0.15s ease"
