        aspectRatio: "1",
        borderRadius: 14,
        border: `1px solid ${T.line}`,
        background: T.surface,
        color: T.ink,
        fontSize: 19,
        fontWeight: 700,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        cursor: busy ? "default" : "pointer",
        opacity: busy ? 0.45 : 1,
        boxShadow: busy ? "none" : T.shadowCard,
        transition: "transform 0.1s ease, box-shadow 0.15s ease, opacity 0.2s ease"
