function notifyReadJson(key, fallback) {
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (e) {
    return fallback;
  }
}
function notifyWriteJson(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    // Losing the dedupe list costs at worst one repeated notification.
  }
}

function paymentNotificationsSupported() {
  return typeof window !== "undefined" && typeof Notification !== "undefined";
}

function paymentNotificationsGranted() {
  return paymentNotificationsSupported() && Notification.permission === "granted";
}

// Asked once, ever. `Notification.permission` alone is not enough to decide
// this: it reads "default" both for someone never asked and for someone who
// dismissed the prompt without choosing, and re-prompting the latter is how
// a browser decides to auto-deny the origin permanently.
function paymentNotificationsAlreadyAsked() {
  return notifyReadJson(GLOOBAL_NOTIFY_ASKED_KEY, false) === true;
}

async function askForPaymentNotifications() {
  if (!paymentNotificationsSupported()) return "unavailable";
  if (Notification.permission !== "default") return Notification.permission;
  if (paymentNotificationsAlreadyAsked()) return Notification.permission;
  notifyWriteJson(GLOOBAL_NOTIFY_ASKED_KEY, true);
  let outcome;
  try {
    outcome = await Notification.requestPermission();
  } catch (e) {
    // Older Safari's callback-only signature rejects the promise form.
    outcome = Notification.permission;
  }
  // Yes is the only moment this app ever gets to register for Web Push:
  // subscribing needs granted permission, and this is the one prompt there
  // is. Doing it here rather than on the next load means notifications for
  // a closed app start working from the payment that earned the yes, not
  // from the next time they happen to open Gloobal. It is deliberately not
  // awaited — the subscribe round-trips to Render, which may be cold, and
  // nothing on the payment screen should wait on that. It cannot throw
  // (see useWebPush.js), so there is nothing to catch.
  // Subscribe only if there is an account to own the subscription.
  //
  // The onboarding permissions screen is the FIRST screen in the app —
  // before the phone number, before registration — so a yes there happens
  // with no session at all. POST /api/push/subscribe is requireAuth, and
  // the route takes the owner from the token and nowhere else, so calling
  // it here would spend a round trip on a guaranteed 401 and register
  // nothing. The device is not lost: gloobalPushSyncOnStart() reconciles
  // on arrival at the dashboard, which is the first moment a subscription
  // can legitimately belong to anybody.
  if (outcome === "granted" && gloobalAuthToken()) gloobalPushSubscribe();
  return outcome;
}

// The Notifications sheet's Enable button (24 September 2026).
//
// It used to call askForPaymentNotifications() and ignore what came back,
// which made it a no-op in the commonest case. That function is guarded to
// ask ONCE EVER, so the app never nags — and the onboarding Alerts card or
// the post-payment offer has usually spent that one ask already. If the
// person dismissed it, permission is still "default", the guard returns
// without calling requestPermission(), the sheet sets "default" again, and
// the button simply reappears. Even a real grant then dropped the subscribe
// result on the floor, so a server with push switched off still looked
// like success.
//
// A tap on Enable is the deliberate request that guard exists to wait for,
// so this path prompts regardless of it (the browser still has the final
// say, and returns immediately if it has quietly blocked the origin), then
// AWAITS the subscribe and reports the real outcome:
//   { state: "ok" }                       subscribed, server row written
//   { state: "denied" }                   blocked; only site settings help
//   { state: "dismissed" }                prompt closed or suppressed
//   { state: "unsupported" }              no Notification/Push API here
//   { state: "signedOut" }                nobody to own a subscription
//   { state: "disabled" | "unreachable" | "failed", error }
//                                         granted, but the subscribe did not
//                                         complete — see gloobalPushSubscribe
// requestPermission() is the first await, so it runs inside the tap's user
// activation as browsers require.
async function enablePaymentNotificationsFromTap() {
  if (!paymentNotificationsSupported() || !gloobalPushSupported()) return { state: "unsupported" };
  let permission = Notification.permission;
  if (permission === "default") {
    notifyWriteJson(GLOOBAL_NOTIFY_ASKED_KEY, true);
    try {
      permission = await Notification.requestPermission();
    } catch (e) {
      permission = Notification.permission;
    }
  }
  if (permission === "denied") return { state: "denied" };
  if (permission !== "granted") return { state: "dismissed" };
  if (!gloobalAuthToken()) return { state: "signedOut" };
  const result = await gloobalPushSubscribe();
  if (result && result.ok) return { state: "ok" };
  const reason = (result && result.reason) || "failed";
  // "default" here means PushManager still says "prompt" although
  // Notification.permission is granted — the same dead end as a dismissal.
  return {
    state: reason === "default" ? "dismissed" : reason,
    error: (result && result.error) || null
  };
}

// One notification per transaction, ever — including across reloads, which
// is why the seen list is persisted rather than held in memory. The received
// poll re-reads the same rows every time it runs, so without this every
// arrival would re-notify on each tick and again on every refresh.
function paymentAlreadyNotified(txnId) {
  if (!txnId) return false;
  return notifyReadJson(GLOOBAL_NOTIFIED_TXNS_KEY, []).indexOf(txnId) !== -1;
}
function markPaymentNotified(txnId) {
  if (!txnId) return;
  const seen = notifyReadJson(GLOOBAL_NOTIFIED_TXNS_KEY, []);
  if (seen.indexOf(txnId) !== -1) return;
  seen.unshift(txnId);
  notifyWriteJson(GLOOBAL_NOTIFIED_TXNS_KEY, seen.slice(0, GLOOBAL_NOTIFIED_TXNS_MAX));
}

// The app icon, as the platform should draw it when there is no per-payment
// disc — and as the BADGE always, which is the small monochrome silhouette
// beside the app name.
//
// This is the same file the service worker names (GLOOBAL_PUSH_ICON in
// push-sw-core.js), and that is the point: the two paths were passing
// different things. The worker sent this path; this file sent
// G_LOGO_DATA_URI, a 300x238 full-colour PNG inline. A badge is reduced to a
// silhouette by the platform, so a full-colour logo and a square app icon do
// not reduce to the same shape — one payment wore two marks depending on
// whether the app happened to be open.
var GLOOBAL_NOTIF_APP_ICON = "/icons/icon-192.png";

// Two ways to put a notification in the tray, and the order between them
// is not a preference.
//
// `new Notification()` — the one this used to use alone — throws outright
// on Android Chrome whenever the page is installed as a PWA, which is
// precisely the case that matters most here. The platform requires
// ServiceWorkerRegistration.showNotification instead, and a worker is
// already registered (vite-plugin-pwa), so that is the primary path now.
// `new Notification()` survives as the fallback for desktop Safari and any
// browser where the worker has not activated yet.
//
// The service-worker path is asynchronous, so this returns true as soon as
// it has committed to showing one rather than when the tray updates. The
// callers use the return value only for their own dedupe bookkeeping, and
// they have already marked the transaction seen before calling.
function showPaymentNotification({ title, body, tag, icon, timestamp }) {
  if (!paymentNotificationsGranted()) return false;
  // `tag` collapses repeats of the same payment into one entry in the
  // tray rather than stacking duplicates.
  //
  // `icon` is the coloured disc this payment is drawn with everywhere else —
  // the same white mark on the same colour as the card in the app, picked
  // from the payment's own reference so the two are the same notification
  // rather than two notifications about one payment. It falls back to the
  // bare mark, which is what this always used to show, if no disc was
  // resolved. `badge` stays the mark: the badge is drawn as a monochrome
  // silhouette, so a colour there would be thrown away.
  // `timestamp` is the instant the platform PRINTS on the notification, and
  // it is the payment's, not this moment's. Left unset it defaults to when
  // the banner was shown — which is close enough while the app is open and
  // wrong for the same payment arriving by push after a delay. The worker
  // has always sent one; this path sent none, so one payment was timed two
  // ways depending on which route it took.
  //
  // `renotify: false` for the same reason it is false there: these two share
  // a tag, so the second of them replaces the first rather than buzzing
  // again, and a repeat is a retry rather than news.
  const options = {
    body,
    tag,
    icon: icon || GLOOBAL_NOTIF_APP_ICON,
    badge: GLOOBAL_NOTIF_APP_ICON,
    timestamp: Number.isFinite(timestamp) ? timestamp : Date.now(),
    renotify: false
  };
  // Both paths refused. Failing quietly is correct: a missing notification
  // must never surface as a broken payment.
  const showDirectly = () => {
    try {
      new Notification(title, options);
      return true;
    } catch (e) {
      return false;
    }
  };
  if (typeof navigator !== "undefined" && navigator.serviceWorker && navigator.serviceWorker.ready) {
    // `serviceWorker.ready` NEVER REJECTS. When no worker is registered for
    // this scope it simply stays pending for ever — which is the normal state
    // on the dev server (devOptions.enabled is false) and on any origin where
    // registration failed. So `.catch` alone could not deliver the fallback
    // this function's header promises: nothing was shown, nothing threw, and
    // the payment notification was silently lost while the function still
    // answered true.
    //
    // Racing a short timer restores that fallback. `settled` makes the two
    // paths exclusive, so a worker that becomes ready late cannot add a
    // second banner for a payment already announced.
    let settled = false;
    const claim = () => (settled ? false : (settled = true));
    navigator.serviceWorker.ready
      .then((registration) => (claim() ? registration.showNotification(title, options) : undefined))
      .catch(() => { if (claim()) showDirectly(); });
    setTimeout(() => { if (claim()) showDirectly(); }, 1500);
    return true;
  }
  return showDirectly();
}

// ── The received-poll baseline ───────────────────────────────────────────
//
// The first successful poll of a dashboard session decides what counts as
// history (marked seen, silent) and what counts as news (notified). It used
// to mark EVERYTHING seen, which is right only if that first poll was also
// the first attempt. When the first attempt failed — a Render cold start —
// or was superseded by the next 30-second tick before it answered, the
// eventual first success could include a payment that landed while the app
// sat open, and it was swallowed as history.
//
// So the baseline remembers when this session started watching (`since`, set
// by the first ATTEMPT, never advanced by a failure) and which attempt primed
// it:
//   - the first attempt itself succeeded → everything is history, exactly as
//     before, with no reliance on clocks;
//   - a later attempt is the first success → rows created at or after
//     `since` arrived while the app was open and are news; older rows, and
//     rows with no usable createdAt, are history.
// Once primed, every row goes to notifyPaymentReceived, whose persisted seen
// list and `gloobal-txn-` tag already stop a second banner for one payment.
//
// `baseline` is a plain { primed, since } object owned by the caller (a ref
// in App.jsx), reset to { primed: false, since: null } when the dashboard is
// left. `rows` is [{ entry, createdAtMs }].
function gloobalReceivedBaselineBegin(baseline, nowMs) {
  if (baseline.since === null) baseline.since = nowMs;
  return nowMs;
}
function gloobalReceivedBaselineSplit(baseline, attemptStartedAt, rows) {
  if (baseline.primed) return { news: rows.map((r) => r.entry), history: [] };
  baseline.primed = true;
  if (attemptStartedAt === baseline.since) return { news: [], history: rows.map((r) => r.entry) };
  const news = [];
  const history = [];
  rows.forEach((r) => {
    if (Number.isFinite(r.createdAtMs) && r.createdAtMs >= baseline.since) news.push(r.entry);
    else history.push(r.entry);
  });
  return { news, history };
}

// Both banners below use the server push's tag, `gloobal-txn-<referenceId>`
// (sendPaymentPushes in server/server.js). With the app open, one payment
// can reach this device twice — the Web Push and this page's own poll — and
// a shared tag makes the second replace the first instead of stacking.

// The tray banner for one payment, whichever direction it went.
//
// Both wordings come from gloobalNotifHeadline / gloobalNotifSubline — the
// same two functions the card in the app uses, and the same two strings the
// server composes for a push when the app is closed. This used to build its
// own: "250.00₹ sent" against the card's "−250.00₹ sent", so the sign that
// tells you which way the money went was present in one place and missing
// in the other. `currencySymbol` is still accepted because callers and
// stored payloads carry it, and a notification is not worth breaking over a
// field on its way out; `currencyCode` is what actually formats the amount.
function notifyPaymentEvent({ direction, txnId, amount, currencySymbol, currencyCode, counterpartyName, occurredAt }) {
  if (paymentAlreadyNotified(txnId)) return false;

  // ── THE PERMISSION GATE BELONGS TO THE TRAY, NOT TO BOTH ─────────────
  //
  // This was the first line of the function, so an account that had never
  // granted notification permission — or had refused it — was told nothing
  // at all. That was right while the only way to tell anybody was the
  // operating system's tray, which genuinely needs permission.
  //
  // ── THE PERMISSION BYPASS WENT WITH THE BANNER ──────────────────────
  //
  // This used to read: visible means the app can tell them, permission
  // or not — because an app needs nobody's permission to draw a card in
  // its own window, and the person who declined the browser prompt was
  // precisely the one who would only ever see what the app drew.
  //
  // That argument was entirely about the banner, and the banner is
  // gone. The tray is now the only route, and the tray needs the grant,
  // so there is nothing left for "visible" to permit.
  //
  // Returns BEFORE marking, deliberately, and that part is unchanged. A
  // payment that could not be reported must stay unreported, so the
  // next poll — after permission is granted — still raises it. Marking
  // here would swallow it permanently.
  if (!paymentNotificationsGranted()) return false;

  markPaymentNotified(txnId);
  const meta = {
    direction,
    amount: Number(amount || 0),
    currency: currencyCode || "",
    counterpartyName: counterpartyName || null
  };
  // Without a currency code there is no table to format against, so the
  // symbol the caller carried is the best that can be said.
  // gloobalNotifHeadline handles a missing figure itself now — it answers
  // "Money sent" / "Money received" rather than a signed zero — so the only
  // reason left to build a string here is a caller that carried a SYMBOL but
  // no currency code, which cannot be formatted by the shared table.
  // 0224: the local form with both names — "+500.00₹, GEU" — which is what
  // the server's push writes too (lib/notificationText.js). The figure here
  // is always this person's own money (what left them, what reached them),
  // so its own currency is passed as theirs and it is named by its sign.
  const title = currencyCode
    ? gloobalNotifHeadline(meta, GEU_LENS_LOCAL, currencyCode)
    : Number.isFinite(Number(amount)) && currencySymbol
      ? `${direction === "sent" ? "\u2212" : "+"}${Number(amount).toFixed(2)}${currencySymbol}`
      : gloobalNotifHeadline({ ...meta, amount: null, currency: null });
  const body = gloobalNotifSubline(meta);

  // ── WHO DRAWS IT ──────────────────────────────────────────────────────
  //
  // With the app in front of the person, the app draws it: the same
  // GloobalNotificationCard the notifications sheet uses, slid down over
  // whatever screen is open (components/cards/paymentBanner.jsx).
  //
  // This used to hand every arrival to the operating system, including the
  // one case where the app was the thing being looked at. Android then drew
  // it in Android's shape — its frame, its app-name line, its chevron — over
  // an app that had a card for exactly this and was not using it. The three
  // surfaces had been made to SAY the same thing; the one surface we control
  // the look of was still borrowing somebody else's.
  //
  // Only while the page is visible. Backgrounded or closed, the tray is the
  // only thing that can reach anybody, and it fires exactly as before — this
  // adds a branch, it removes nothing.
  //
  // A DOM event rather than a callback: this module is plain functions with
  // no route into the React tree, which is the same reason
  // gloobal:sessionExpired and gloobal:openNotifications are events.
  // ── MONEY MOVED, WHILE THIS PAGE WAS LOOKING ────────────────────────
  //
  // Still fired, and no longer a branch. It used to decide WHO DREW the
  // notification — the app, as a banner, when the page was visible;
  // the tray otherwise — which made one event appear in two shapes
  // depending on where the person's eyes were. The banner is gone, so
  // this is now only what its name says: a signal that money moved
  // while this page was open. My Choices reloads its totals on it.
  //
  // Dispatched whether or not the page is visible, because a listener
  // that wants it only when visible can ask, and one that wants it
  // always could not have had it before.
  if (typeof window !== "undefined" && typeof window.dispatchEvent === "function") {
    window.dispatchEvent(new CustomEvent("gloobal:paymentBanner", {
      detail: { ...meta, txnId, title, body, occurredAt: occurredAt || null }
    }));
  }

  return showPaymentNotification({
    title,
    body,
    tag: `gloobal-txn-${txnId || "unknown"}`,
    // The app logo in its colour for these two hours — the same picture
    // the service worker shows for a push (push-sw-core.js), so a payment
    // looks the same in the tray whether the app was open or not.
    icon: gloobalLogoIconPath(gloobalLogoColorAt(Date.now()).key, 192),
    // When the money moved, which is what the platform prints on the
    // notification. The same instant the card's Date and time page shows
    // and the receipt prints.
    timestamp: occurredAt ? Date.parse(occurredAt) : NaN
  });
}

// Money has arrived. The one people actually want.
function notifyPaymentReceived({ txnId, amount, currencySymbol, currencyCode, from, occurredAt }) {
  return notifyPaymentEvent({ direction: "received", txnId, amount, currencySymbol, currencyCode, counterpartyName: from, occurredAt });
}

// Confirmation of a payment this device just made. It reads exactly like an
// arrival now, and deliberately: it used to be worded more quietly on the
// argument that the person is holding the phone and already saw the success
// screen — true at the moment it appears, and wrong an hour later when it is
// one line in a tray next to the other one and has to say the same kind of
// thing.
function notifyPaymentSent({ txnId, amount, currencySymbol, currencyCode, to, occurredAt }) {
  return notifyPaymentEvent({ direction: "sent", txnId, amount, currencySymbol, currencyCode, counterpartyName: to, occurredAt });
}

// Called after a payment succeeds. Asks at most once in the account's
// lifetime, and only when there is something real to offer.
async function offerPaymentNotificationsAfterPayment() {
  if (!paymentNotificationsSupported()) return;
  if (Notification.permission !== "default") return;
  if (paymentNotificationsAlreadyAsked()) return;
  await askForPaymentNotifications();
}

// A shared device must not carry one account's dedupe list into the next
// person's session, or their first genuine arrival could be swallowed as
// "already notified".
function forgetPaymentNotifications() {
  try {
    window.localStorage.removeItem(GLOOBAL_NOTIFIED_TXNS_KEY);
  } catch (e) {
    // Same reasoning as the writes above.
  }
}


// ── THE COUNTER SOUNDBOX ───────────────────────────────────────────────
//
// When a payment to the CREATOR side is confirmed by the server, the phone
// plays a short two-note chime and then says the amount out loud —
// "Received 500 Indian rupees" — so a shopkeeper serving the next customer
// knows the money landed without looking at the screen.
//
// Only ever for a payment the server has recorded: App.jsx calls this from
// the received-payments read (GET /api/transactions), never from anything
// the payer's phone says. A screenshot of a "payment successful" screen
// makes no sound here.
//
// The chime is drawn with the Web Audio API (two sine notes with a soft
// overtone and a quick fade), so there is no sound file to download. The
// amount is spoken by the phone's own voice (speechSynthesis). Either can be
// missing on a given device; each is skipped on its own.
//
// Browsers only allow sound after the person has touched the page once.
// The first tap anywhere in the app unlocks both (gloobalChimeUnlock), so by
// the time a customer pays, the counter phone is ready.
//
// Works while the app is open, in front or behind another tab. With the
// app fully closed, the phone's normal notification sound plays instead —
// a closed web app cannot run Web Audio or speak.

var gloobalChimeContext = null;
var gloobalChimeEnabled = true;
var gloobalChimePlayed = new Set();
var gloobalChimeQueue = Promise.resolve();

// The account's "Payment sound" switch, mirrored here from
// User.securitySettings.paymentSound. App.jsx sets it whenever the account
// changes. Defaults to on, matching the server.
function gloobalSetPaymentSoundEnabled(enabled) {
  gloobalChimeEnabled = enabled !== false;
}

function gloobalChimeAudioContext() {
  if (gloobalChimeContext) return gloobalChimeContext;
  if (typeof window === "undefined") return null;
  var Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null;
  try {
    gloobalChimeContext = new Ctor();
  } catch (e) {
    gloobalChimeContext = null;
  }
  return gloobalChimeContext;
}

// Called on the first touch or key press. Creates (or resumes) the audio
// context and primes the voice with a silent utterance, which is what the
// browser's autoplay rules ask for.
function gloobalChimeUnlock() {
  var ctx = gloobalChimeAudioContext();
  if (ctx && ctx.state === "suspended" && typeof ctx.resume === "function") {
    ctx.resume().catch(function () {});
  }
  try {
    if (typeof window !== "undefined" && window.speechSynthesis && typeof SpeechSynthesisUtterance !== "undefined") {
      var silent = new SpeechSynthesisUtterance(" ");
      silent.volume = 0;
      window.speechSynthesis.speak(silent);
    }
  } catch (e) {
    /* no voice on this device */
  }
}

(function gloobalChimeInstallUnlock() {
  if (typeof window === "undefined" || typeof window.addEventListener !== "function") return;
  var done = false;
  var once = function () {
    if (done) return;
    done = true;
    gloobalChimeUnlock();
    window.removeEventListener("pointerdown", once, true);
    window.removeEventListener("keydown", once, true);
    window.removeEventListener("touchstart", once, true);
  };
  window.addEventListener("pointerdown", once, true);
  window.addEventListener("keydown", once, true);
  window.addEventListener("touchstart", once, true);
})();

// One bell-like note: a sine at the pitch plus a quieter one an octave up,
// rising in 6 ms and fading out over `length` seconds.
function gloobalChimeNote(ctx, frequency, startAt, length, level) {
  var out = ctx.createGain();
  out.gain.setValueAtTime(0.0001, startAt);
  out.gain.exponentialRampToValueAtTime(level, startAt + 0.006);
  out.gain.exponentialRampToValueAtTime(0.0001, startAt + length);
  out.connect(ctx.destination);
  [[frequency, 1], [frequency * 2, 0.28]].forEach(function (partial) {
    var osc = ctx.createOscillator();
    var amp = ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(partial[0], startAt);
    amp.gain.setValueAtTime(partial[1], startAt);
    osc.connect(amp);
    amp.connect(out);
    osc.start(startAt);
    osc.stop(startAt + length + 0.05);
  });
}

// The chime itself: C6 then G6, the second ringing a little longer.
// Resolves when it has finished, so the voice starts after it.
function gloobalPlayChimeTone() {
  return new Promise(function (resolve) {
    var ctx = gloobalChimeAudioContext();
    if (!ctx) return resolve(false);
    var play = function () {
      try {
        var now = ctx.currentTime + 0.02;
        gloobalChimeNote(ctx, 1046.5, now, 0.55, 0.22);
        gloobalChimeNote(ctx, 1568.0, now + 0.13, 0.8, 0.2);
        setTimeout(function () { resolve(true); }, 650);
      } catch (e) {
        resolve(false);
      }
    };
    if (ctx.state === "suspended" && typeof ctx.resume === "function") {
      ctx.resume().then(play, function () { resolve(false); });
    } else {
      play();
    }
  });
}

// What the phone says. The amount in words the voice reads naturally —
// "500 Indian rupees", not "₹500" — in Hindi on a Hindi phone, otherwise in
// English (the voice reads an English sentence correctly on any phone; a
// sentence half in another language does not).
function gloobalChimeSentence(amount, currency, language) {
  var lang = String(language || "en").toLowerCase();
  var whole = Math.abs(amount - Math.round(amount)) < 0.005;
  var useHindi = lang.indexOf("hi") === 0;
  var locale = useHindi ? "hi-IN" : "en-" + ((lang.split("-")[1] || "US").toUpperCase());
  var spoken;
  try {
    spoken = new Intl.NumberFormat(locale, {
      style: "currency",
      currency: currency || "USD",
      currencyDisplay: "name",
      minimumFractionDigits: whole ? 0 : 2,
      maximumFractionDigits: whole ? 0 : 2
    }).format(amount);
  } catch (e) {
    spoken = String(whole ? Math.round(amount) : amount.toFixed(2)) + " " + (currency || "");
  }
  return useHindi
    ? { text: spoken + " प्राप्त हुए", lang: "hi-IN" }
    : { text: "Received " + spoken, lang: locale };
}

// ── YOUR OWN ANNOUNCEMENT ───────────────────────────────────────────────
//
// The founder, 10 Nov: like the soundbox on a shop counter, but the shop
// writes what it says — "100 CEL prapt hue, aapka dhanyavaad". The line is
// kept on this phone (localStorage); {amount} marks where the amount goes,
// and a line with no {amount} has the amount said first. No line saved
// means the standard sentence above.
var GLOOBAL_PAYMENT_LINE_KEY = "gloobal.paymentLine";
var GLOOBAL_PAYMENT_LINE_MAX = 80;
var GLOOBAL_PAYMENT_LINE_PRESETS = [
  "{amount} CEL prapt hue, aapka dhanyavaad",
  "{amount} CEL प्राप्त हुए, आपका धन्यवाद",
  "Received {amount} CEL. Thank you!",
  "{amount} CEL aa gaye. Phir aaiyega!"
];
function gloobalPaymentLineLoad() {
  try {
    if (typeof localStorage === "undefined") return "";
    var raw = localStorage.getItem(GLOOBAL_PAYMENT_LINE_KEY);
    return typeof raw === "string" ? raw.slice(0, GLOOBAL_PAYMENT_LINE_MAX).trim() : "";
  } catch (e) {
    return "";
  }
}
function gloobalPaymentLineSave(text) {
  try {
    var clean = String(text || "").slice(0, GLOOBAL_PAYMENT_LINE_MAX).trim();
    if (clean) localStorage.setItem(GLOOBAL_PAYMENT_LINE_KEY, clean);
    else localStorage.removeItem(GLOOBAL_PAYMENT_LINE_KEY);
    return true;
  } catch (e) {
    return false;
  }
}
// The line with the amount in it. The number is said plainly ("100", or
// "100.50"), because the line names the unit itself. Devanagari is read by
// a Hindi voice; Latin letters (English or Hinglish) by an Indian-English
// one, which says "prapt hue" as written.
function gloobalPaymentLineSentence(template, amount) {
  var whole = Math.abs(amount - Math.round(amount)) < 0.005;
  var number = whole ? String(Math.round(amount)) : amount.toFixed(2);
  var line = String(template || "").trim();
  var text = /\{amount\}/i.test(line) ? line.replace(/\{amount\}/gi, number) : number + ". " + line;
  return { text: text, lang: /[\u0900-\u097F]/.test(text) ? "hi-IN" : "en-IN" };
}
// Or an audio clip in place of the words: the shop's own voice or jingle,
// five seconds at most (recorded or uploaded in the Creator profile, cut
// to length by soundPayClipFromFile / soundPayRecordLine). A clip cannot
// say a number, so the amount is spoken straight after it: the soundbox's
// one job is that the shopkeeper hears how much came.
var GLOOBAL_PAYMENT_CLIP_KEY = "gloobal.paymentClip";
var GLOOBAL_PAYMENT_CLIP_MAX_MS = 5000;
function gloobalPaymentClipLoad() {
  try {
    if (typeof localStorage === "undefined") return "";
    var raw = localStorage.getItem(GLOOBAL_PAYMENT_CLIP_KEY);
    return typeof raw === "string" && raw.indexOf("data:audio/") === 0 ? raw : "";
  } catch (e) {
    return "";
  }
}
function gloobalPaymentClipSave(url) {
  try {
    if (url) localStorage.setItem(GLOOBAL_PAYMENT_CLIP_KEY, String(url));
    else localStorage.removeItem(GLOOBAL_PAYMENT_CLIP_KEY);
    return true;
  } catch (e) {
    return false;
  }
}
// Plays the clip; resolves when it ends, fails, or five seconds have gone.
function gloobalPlayClip(url) {
  return new Promise(function (resolve) {
    var done = false;
    var audio = null;
    var finish = function (ok) {
      if (done) return;
      done = true;
      try { if (audio) audio.pause(); } catch (e) { /* already stopped */ }
      resolve(ok);
    };
    try {
      if (!url || typeof Audio === "undefined") return resolve(false);
      audio = new Audio(url);
      audio.onended = function () { finish(true); };
      audio.onerror = function () { finish(false); };
      setTimeout(function () { finish(true); }, GLOOBAL_PAYMENT_CLIP_MAX_MS + 300);
      var p = audio.play();
      if (p && p.catch) p.catch(function () { finish(false); });
    } catch (e) {
      finish(false);
    }
  });
}
function gloobalPaymentAmountOnly(amount) {
  return gloobalPaymentLineSentence("{amount} " + (typeof COIN_TICKER !== "undefined" ? COIN_TICKER : "CEL"), amount);
}

// ── HOW IT IS SAID ──────────────────────────────────────────────────────
//
// The Payment sound screen's other choices, kept on this phone beside the
// line and the clip:
//   mode        "line" (speak the words), "clip" (the shop's audio), or
//               "chime" (the two notes and nothing else)
//   voice       "auto" (the voice that suits the line's letters), "hi", "en"
//   speed       "slow" | "normal" | "fast"
//   clipAmount  after a clip, say "…100 CEL" (on unless switched off)
// Nothing saved means what the app did before this screen existed: the clip
// if there is one, otherwise the words, voice by the letters, amount said.
var GLOOBAL_PAYMENT_SOUND_KEY = "gloobal.paymentSound";
var GLOOBAL_PAYMENT_SPEEDS = { slow: 0.78, normal: 0.95, fast: 1.2 };
function gloobalPaymentSoundPrefs() {
  var saved = {};
  try {
    if (typeof localStorage !== "undefined") saved = JSON.parse(localStorage.getItem(GLOOBAL_PAYMENT_SOUND_KEY) || "{}") || {};
  } catch (e) {
    saved = {};
  }
  var hasClip = !!gloobalPaymentClipLoad();
  var mode = saved.mode === "chime" ? "chime" : saved.mode === "line" ? "line" : saved.mode === "clip" ? "clip" : hasClip ? "clip" : "line";
  if (mode === "clip" && !hasClip) mode = "line";
  return {
    mode: mode,
    voice: saved.voice === "hi" || saved.voice === "en" ? saved.voice : "auto",
    speed: GLOOBAL_PAYMENT_SPEEDS[saved.speed] ? saved.speed : "normal",
    clipAmount: saved.clipAmount !== false
  };
}
function gloobalPaymentSoundPrefsSave(prefs) {
  try {
    var p = prefs || {};
    localStorage.setItem(GLOOBAL_PAYMENT_SOUND_KEY, JSON.stringify({
      mode: p.mode === "chime" || p.mode === "clip" ? p.mode : "line",
      voice: p.voice === "hi" || p.voice === "en" ? p.voice : "auto",
      speed: GLOOBAL_PAYMENT_SPEEDS[p.speed] ? p.speed : "normal",
      clipAmount: p.clipAmount !== false
    }));
    return true;
  } catch (e) {
    return false;
  }
}
// One announcement, played the way `how` says: the chime, then the words,
// or the clip (and the amount), or nothing more. `how` is the saved choice
// for a real payment and the unsaved draft for "hear it" on the screen.
function gloobalPlayPaymentSound(how, amount, currency, language) {
  var h = how || {};
  var say = { voice: h.voice, speed: h.speed };
  return gloobalPlayChimeTone().then(function () {
    if (h.mode === "chime") return true;
    if (h.mode === "clip" && h.clip) {
      return gloobalPlayClip(h.clip).then(function (ok) {
        return h.clipAmount === false ? ok : gloobalSpeak(gloobalPaymentAmountOnly(amount), say);
      });
    }
    var line = String(h.line || "").trim();
    return gloobalSpeak(line ? gloobalPaymentLineSentence(line, amount) : gloobalChimeSentence(amount, currency, language), say);
  });
}
// "Hear it" on the Payment sound screen: the draft as it stands, from a tap.
function gloobalPreviewPaymentSound(draft, amount, currency) {
  gloobalChimeUnlock();
  try { if (typeof window !== "undefined" && window.speechSynthesis && window.speechSynthesis.cancel) window.speechSynthesis.cancel(); } catch (e) { /* nothing was speaking */ }
  return gloobalPlayPaymentSound(draft, amount || 100, currency, typeof navigator !== "undefined" ? navigator.language : "en");
}

// What a payment of `amount` will say on this phone right now.
function gloobalPaymentSentence(amount, currency, language) {
  var custom = gloobalPaymentLineLoad();
  return custom ? gloobalPaymentLineSentence(custom, amount) : gloobalChimeSentence(amount, currency, language);
}
// "Hear it": the chime, then the line with a sample amount. From a tap.
function gloobalPreviewPaymentLine(template, currency) {
  gloobalChimeUnlock();
  var language = typeof navigator !== "undefined" ? navigator.language : "en";
  var clip = gloobalPaymentClipLoad();
  if (clip) return gloobalPlayChimeTone().then(function () { return gloobalPlayClip(clip); }).then(function () { return gloobalSpeak(gloobalPaymentAmountOnly(100)); });
  var sentence = String(template || "").trim() ? gloobalPaymentLineSentence(template, 100) : gloobalChimeSentence(100, currency, language);
  return gloobalPlayChimeTone().then(function () { return gloobalSpeak(sentence); });
}

// CEL is a word, said "sel" — never the letters C, E, L, which is what a
// phone's voice does with three capitals. So the spoken text (only that;
// what is shown stays CEL) carries a spelling the voice reads as a word:
// "Cell" for a Latin-letter voice, "सेल" inside a Hindi sentence.
function gloobalSpokenText(text, lang) {
  var hindi = String(lang || "").toLowerCase().indexOf("hi") === 0 && /[\u0900-\u097F]/.test(text);
  return String(text || "").replace(/(^|[^A-Za-z])CEL(?![A-Za-z])/gi, function (m, before) { return before + (hindi ? "सेल" : "Cell"); });
}
function gloobalSpeak(sentence, how) {
  return new Promise(function (resolve) {
    try {
      if (typeof window === "undefined" || !window.speechSynthesis || typeof SpeechSynthesisUtterance === "undefined") {
        return resolve(false);
      }
      // The shop's choice of voice wins over the one the letters suggest.
      var want = how && how.voice === "hi" ? "hi-IN" : how && how.voice === "en" ? "en-IN" : sentence.lang;
      sentence = { text: gloobalSpokenText(sentence.text, want), lang: want };
      var u = new SpeechSynthesisUtterance(sentence.text);
      u.lang = sentence.lang;
      u.rate = (how && GLOOBAL_PAYMENT_SPEEDS[how.speed]) || 0.95;
      u.volume = 1;
      var voices = window.speechSynthesis.getVoices ? window.speechSynthesis.getVoices() : [];
      var match = voices.filter(function (v) { return v.lang && v.lang.toLowerCase() === sentence.lang.toLowerCase(); })[0] ||
        voices.filter(function (v) { return v.lang && v.lang.slice(0, 2).toLowerCase() === sentence.lang.slice(0, 2).toLowerCase(); })[0];
      if (match) u.voice = match;
      // Never hang the queue on a voice that never reports back.
      var finished = false;
      var finish = function (ok) { if (!finished) { finished = true; resolve(ok); } };
      u.onend = function () { finish(true); };
      u.onerror = function () { finish(false); };
      setTimeout(function () { finish(false); }, 6000);
      window.speechSynthesis.speak(u);
    } catch (e) {
      resolve(false);
    }
  });
}

// Plays one confirmed creator payment: chime, then the amount. Payments
// that arrive together are announced one after another, never over each
// other, and each payment at most once.
function gloobalPlayPaymentChime(payment) {
  var p = payment || {};
  if (!gloobalChimeEnabled) return Promise.resolve(false);
  var key = String(p.txnId || "");
  if (!key || gloobalChimePlayed.has(key)) return Promise.resolve(false);
  gloobalChimePlayed.add(key);
  var amount = Number(p.amount);
  if (!Number.isFinite(amount) || amount <= 0) return Promise.resolve(false);
  var language = p.language || (typeof navigator !== "undefined" ? navigator.language : "en");
  var how = gloobalPaymentSoundPrefs();
  how.line = gloobalPaymentLineLoad();
  how.clip = gloobalPaymentClipLoad();
  gloobalChimeQueue = gloobalChimeQueue.then(function () {
    return gloobalPlayPaymentSound(how, amount, p.currency, language);
  }).catch(function () { return false; });
  return gloobalChimeQueue;
}

// A payment the app already knew about when it opened is history, not
// news: marked as played without a sound.
function gloobalMarkChimePlayed(txnId) {
  if (txnId) gloobalChimePlayed.add(String(txnId));
}

// ── THE SIDE SWITCH ────────────────────────────────────────────────────
//
// A short sound when the account flips between its Personal and Creator
// sides, so the switch is heard as well as seen. Two quick notes that RISE
// going to Creator (opening the shop) and FALL going back to Personal,
// with a soft pitch slide on each so it reads as a turn rather than a
// beep. Quieter and shorter than the payment chime, so the two are never
// confused at a counter.
//
// Follows the same "Sounds" switch as the payment chime. Always played
// from the tap itself, so the browser's sound rules are already met.
function gloobalPlayRoleSwitchSound(side) {
  if (!gloobalChimeEnabled) return false;
  var ctx = gloobalChimeAudioContext();
  if (!ctx) return false;
  var toCreator = side === "merchant" || side === "creator";
  var play = function () {
    try {
      var now = ctx.currentTime + 0.01;
      var notes = toCreator ? [[659.3, 784.0], [987.8, 1318.5]] : [[987.8, 880.0], [659.3, 523.3]];
      notes.forEach(function (pair, i) {
        var at = now + i * 0.085;
        var out = ctx.createGain();
        out.gain.setValueAtTime(0.0001, at);
        out.gain.exponentialRampToValueAtTime(0.12, at + 0.008);
        out.gain.exponentialRampToValueAtTime(0.0001, at + 0.22);
        out.connect(ctx.destination);
        var osc = ctx.createOscillator();
        osc.type = "triangle";
        osc.frequency.setValueAtTime(pair[0], at);
        osc.frequency.exponentialRampToValueAtTime(pair[1], at + 0.07);
        osc.connect(out);
        osc.start(at);
        osc.stop(at + 0.26);
      });
    } catch (e) {
      /* a missing sound never blocks the switch */
    }
  };
  if (ctx.state === "suspended" && typeof ctx.resume === "function") {
    ctx.resume().then(play, function () {});
  } else {
    play();
  }
  return true;
}


// src/hooks/useWebPush.js
//
// Web Push: the half of notifications that survives the app being closed.
//
// hooks/usePaymentNotifications.js does local notifications — fired by this
// page while it is running. Its own header note says what it cannot do:
// reach someone who has fully closed Gloobal. This file is that missing
// piece. It owns the device's PushSubscription and the server row that
// names it, and nothing else: the permission prompt still belongs to
// usePaymentNotifications, and is still asked exactly once, after a
// payment, never on load.
//
// ── What a subscription actually is ──────────────────────────────────────
//
// A PushSubscription is issued by the BROWSER's push service (FCM, Mozilla
// autopush, Apple's) and identifies a browser profile on a device. It says
// nothing about who is signed in. The account it belongs to is entirely a
// fact about the row the server stores against it — which is why the order
// of operations matters so much here:
//
//   signing out   → unsubscribe BEFORE the token is cleared, or the row is
//                   orphaned and the next person's device keeps receiving
//                   the previous person's payments.
//   switching     → unsubscribe then re-subscribe, so the row names the
//                   account that is signed in NOW.
//   starting up   → reconcile: re-POST, because the endpoint may have been
//                   rotated by the browser while the app was closed and
//                   the server would be pushing into a dead endpoint.
//
// ── The stale-key trap ───────────────────────────────────────────────────
//
// `pushManager.subscribe()` REJECTS if called with a different
// applicationServerKey than the existing subscription was created with —
// and a subscription created against a rotated VAPID key still looks
// perfectly healthy from the client while every push sent to it is
// rejected by the push service. So gloobalPushSubscribe compares the key
// bytes and unsubscribes first when they differ, rather than assuming an
// existing subscription is a usable one.
//
// ── Unreachable is not unauthorised ──────────────────────────────────────
//
// Every call here goes through httpClient.js, where `status === 0` means
// the request never got an answer — offline, or Render cold-starting from
// its free-tier sleep, which takes up to 45 seconds. That is not a signal
// about anything. None of these functions clears a subscription, a token
// or a session on it; they report "unreachable" and leave every piece of
// state exactly where it was, to be reconciled on the next start.
//
// Nothing here throws. A notification that fails to arrive must never be
// the reason a payment screen breaks.

function gloobalPushSupported() {
  return typeof navigator !== "undefined"
    && "serviceWorker" in navigator
    && typeof window !== "undefined"
    && "PushManager" in window
    && typeof Notification !== "undefined";
}

// VAPID public keys travel as base64url with the padding stripped, and
// `applicationServerKey` wants raw bytes. This is the standard conversion:
// restore the padding, translate the URL-safe alphabet back, decode.
function gloobalPushUrlBase64ToUint8Array(base64) {
  const raw = String(base64 || "");
  const padding = "=".repeat((4 - (raw.length % 4)) % 4);
  const normalised = (raw + padding).replace(/-/g, "+").replace(/_/g, "/");
  const binary = window.atob(normalised);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

// Byte-for-byte comparison of an existing subscription's key against the
// one the server is handing out now. `options.applicationServerKey` is an
// ArrayBuffer, and is absent on older Safari — absent is treated as "can't
// tell", which means re-subscribing, which is the safe direction.
function gloobalPushKeyMatches(subscription, wantedBytes) {
  try {
    const existing = subscription && subscription.options && subscription.options.applicationServerKey;
    if (!existing) return false;
    const have = new Uint8Array(existing);
    if (have.length !== wantedBytes.length) return false;
    for (let i = 0; i < have.length; i += 1) {
      if (have[i] !== wantedBytes[i]) return false;
    }
    return true;
  } catch (e) {
    return false;
  }
}

// Every result is one of these shapes. A caller never has to catch.
//   { ok: true, subscription }             — the server row matches this device
//   { ok: false, reason: "unsupported" }   — no service worker / PushManager
//   { ok: false, reason: "denied" }        — the browser said no
//   { ok: false, reason: "default" }       — never asked; not this file's job
//   { ok: false, reason: "disabled" }      — server has no VAPID keys
//   { ok: false, reason: "unreachable" }   — offline or cold start; retry later
//   { ok: false, reason: "failed", error } — anything else
function gloobalPushResult(reason, error) {
  return { ok: false, reason: reason, error: error || null };
}

// The endpoint of whatever subscription this page last saw, remembered the
// moment it is known.
//
// This exists for exactly one caller: sign-out. Dropping the server row is
// an authenticated call, so it has to go out while the bearer token is
// still there — and sign-out clears the token synchronously, in the same
// tick. Looking the endpoint up properly means awaiting
// `serviceWorker.ready` and `getSubscription()` first, two async hops, by
// which time the token is gone and the call comes back 401 with the row
// left behind. Caching it makes the POST startable in the same tick the
// button is pressed.
var gloobalPushKnownEndpoint = "";

// Subscribes this device and tells the server. Assumes permission is
// already granted — it does NOT prompt, because the prompt is a one-shot
// resource spent deliberately elsewhere (see usePaymentNotifications).
async function gloobalPushSubscribe({ promotional } = {}) {
  if (!gloobalPushSupported()) return gloobalPushResult("unsupported");
  if (Notification.permission === "denied") return gloobalPushResult("denied");
  if (Notification.permission !== "granted") return gloobalPushResult("default");

  let keyInfo;
  try {
    keyInfo = await GloobalApi.getPushPublicKey();
  } catch (err) {
    if (gloobalApiIsUnreachable(err)) return gloobalPushResult("unreachable", err);
    return gloobalPushResult("failed", err);
  }
  if (!keyInfo || !keyInfo.enabled || !keyInfo.publicKey) return gloobalPushResult("disabled");

  let applicationServerKey;
  try {
    applicationServerKey = gloobalPushUrlBase64ToUint8Array(keyInfo.publicKey);
  } catch (err) {
    return gloobalPushResult("failed", err);
  }

  let subscription = null;
  try {
    // `ready` resolves once a worker is active for this scope. It never
    // rejects, but it also never resolves if registration failed outright,
    // which is why it is inside the try with everything else.
    const registration = await navigator.serviceWorker.ready;
    // PushManager.permissionState() answers about PUSH, which is not the
    // same question as Notification.permission. A browser can hold
    // notifications granted while push itself is blocked — by policy, by a
    // profile setting, or because the origin lost the permission after the
    // page read it. Asking the push manager directly is the only way to see
    // that, and it saves a subscribe() that would throw. Where it does not
    // exist, Notification.permission (already checked above) stands.
    if (typeof registration.pushManager.permissionState === "function") {
      try {
        const pushPerm = await registration.pushManager.permissionState({ userVisibleOnly: true });
        if (pushPerm === "denied") return gloobalPushResult("denied");
        if (pushPerm === "prompt") return gloobalPushResult("default");
      } catch (e) {
        // Older implementations reject rather than answer. Not a reason to
        // abandon a subscribe that Notification.permission already allows.
      }
    }
    const existing = await registration.pushManager.getSubscription();
    if (existing && gloobalPushKeyMatches(existing, applicationServerKey)) {
      // Still valid for the current key. Reuse it — re-subscribing would
      // hand out a new endpoint and leave the old row behind on the server.
      subscription = existing;
    } else {
      if (existing) {
        // Created against a key the server no longer signs with. It would
        // keep looking healthy here while every push to it was dropped.
        try { await existing.unsubscribe(); } catch (e) { /* already gone */ }
      }
      subscription = await registration.pushManager.subscribe({
        // Required by Chrome: a push may only be received if it results in
        // something the person can see. Everything Gloobal sends does.
        userVisibleOnly: true,
        applicationServerKey: applicationServerKey
      });
    }
  } catch (err) {
    return gloobalPushResult("failed", err);
  }

  gloobalPushKnownEndpoint = (subscription && subscription.endpoint) || "";
  try {
    // `promotional` is passed through UNCOERCED. Boolean(undefined) is false,
    // and a literal false is an explicit "do not market to me" that the
    // subscribe route writes over any existing opt-in — so coercing here made
    // every start-up reconcile reset a preference the person had set.
    await GloobalApi.savePushSubscription(subscription.toJSON(), { promotional: promotional });
  } catch (err) {
    if (gloobalApiIsUnreachable(err)) {
      // The local subscription is real and good; only the server row is
      // missing. Leaving it in place means the next start reconciles it
      // rather than starting from nothing.
      return gloobalPushResult("unreachable", err);
    }
    return gloobalPushResult("failed", err);
  }
  return { ok: true, subscription: subscription };
}

// Called once when a session goes live, and again whenever the worker
// reports that the browser rotated this device's subscription.
//
// This is a reconciliation, not a setup step: it exists because the app
// spends most of its life closed, during which the endpoint can be rotated
// or the server row can be dropped, and neither event produces anything
// the page can observe later. Re-POSTing an unchanged subscription is
// cheap and idempotent; not doing it is a device that silently stops
// receiving.
async function gloobalPushSyncOnStart({ promotional } = {}) {
  if (!gloobalPushSupported()) return gloobalPushResult("unsupported");
  // Permission is asked exactly once, after a payment, by
  // usePaymentNotifications. Anything other than "granted" here is a
  // question that has been answered or not yet earned — never a reason to
  // prompt on load.
  if (Notification.permission !== "granted") {
    return gloobalPushResult(Notification.permission === "denied" ? "denied" : "default");
  }
  return await gloobalPushSubscribe({ promotional: promotional });
}

// Drops the server's row FIRST, then the local subscription.
//
// The order is the whole point. The unsubscribe call is authenticated by
// the bearer token; run it after the session is cleared and it comes back
// 401, the row survives, and the server goes on pushing this person's
// payments to a device somebody else is now holding. Locally unsubscribing
// afterwards is the cheap half and cannot fail in a way that matters.
//
// Deliberately NOT declared `async`. An async function's body runs
// synchronously only up to its first `await`, and this must start the
// server call before returning to its caller — sign-out clears the token
// on the very next line. httpClient reads the token when the request is
// built, before its own first await, so a call STARTED here is a call
// carrying the right credential even though it finishes long after the
// session is gone.
function gloobalPushUnsubscribe() {
  if (!gloobalPushSupported()) return Promise.resolve(gloobalPushResult("unsupported"));

  const endpoint = gloobalPushKnownEndpoint;
  gloobalPushKnownEndpoint = "";
  // Started here, in this tick, while the token still exists.
  const serverDone = endpoint
    ? GloobalApi.deletePushSubscription(endpoint).then(
      () => null,
      (err) => (gloobalApiIsUnreachable(err) ? "unreachable" : "failed")
    )
    : Promise.resolve(null);

  // The local half can take its time. It is also the half that must happen
  // regardless of what the server said: the person asked to sign out, and
  // this device has to stop receiving even if the row could not be dropped.
  const localDone = Promise.resolve()
    .then(() => navigator.serviceWorker.ready)
    .then((registration) => registration.pushManager.getSubscription())
    .then((subscription) => {
      if (!subscription) return null;
      // No cached endpoint — this page never subscribed during this
      // session, so the POST above did not go out. Send it now, accepting
      // that it may already be too late to be authenticated; a 401 here
      // leaves a row that the next sign-in on this device replaces anyway,
      // because the endpoint is the same and the server upserts on it.
      if (!endpoint) {
        return GloobalApi.deletePushSubscription(subscription.endpoint)
          .catch(() => null)
          .then(() => subscription.unsubscribe());
      }
      return subscription.unsubscribe();
    })
    .catch(() => null);

  return Promise.all([serverDone, localDone]).then(([serverReason]) => (
    serverReason ? gloobalPushResult(serverReason) : { ok: true, subscription: null }
  ));
}

// The one preference there is. Transactional pushes are not a preference —
// they are the notice that money moved.
async function gloobalPushSetPromotional(optIn) {
  if (!gloobalPushSupported()) return gloobalPushResult("unsupported");
  try {
    const result = await GloobalApi.setPushPreferences(Boolean(optIn));
    return { ok: true, promotional: Boolean(result && result.promotional) };
  } catch (err) {
    if (gloobalApiIsUnreachable(err)) return gloobalPushResult("unreachable", err);
    return gloobalPushResult("failed", err);
  }
}

// The app icon's own badge — the little count on the home-screen icon of an
// installed PWA. Supported on installed PWAs in Chromium and Safari, absent
// everywhere else, hence the optional calls: on a browser without it this
// does nothing at all, which is the correct amount.
function gloobalPushSetAppBadge(unreadCount) {
  try {
    const n = Number(unreadCount) || 0;
    if (typeof navigator === "undefined") return;
    if (n > 0) navigator.setAppBadge?.(n);
    else navigator.clearAppBadge?.();
  } catch (e) {
    // Badging throws in some embedded webviews. Never worth a crash.
  }
}


// src/hooks/useAmbientFlags.js
var AMBIENT_FLAG_CODES = ["US", "BR", "IN", "JP", "FR", "DE", "GB", "AU", "CA", "ZA", "MX", "KR", "ES", "AE"];
function useAmbientFlags() {
  return useMemo7(
    () => AMBIENT_FLAG_CODES.map((code, i) => ({
      code,
      flag: COUNTRY_BY_ISO[code]?.flag || isoToFlag(code),
      top: i * 37 % 92 + 2,
      left: i * 53 % 90 + 2,
      size: 24 + i * 7 % 5 * 6,
      duration: 24 + i * 5 % 6 * 3,
      delay: -(i * 11 % 20),
      dx: (i % 2 === 0 ? 1 : -1) * (18 + i % 4 * 6),
      dy: (i % 3 === 0 ? -1 : 1) * (14 + i % 5 * 5)
    })),
    []
  );
}



// src/features/geuLens/geuLens.js
//
// GEU, as a lens over money somebody already has.
//
// ── What GEU is now, and what it stopped being ──────────────────────────
//
// It was a second balance: User.coinBalance, backed 1:1 by a reserve, with
// routes to buy it, sell it and send it. All of that is deleted and every
// holding was redeemed back to spendable fiat before it was.
//
// GEU is a LABEL. One unit of it is one unit of the viewer's own legal
// tender, permanently and everywhere:
//
//     India    1 GEU = ₹1
//     USA      1 GEU = $1
//     Japan    1 GEU = ¥1
//
// So ₹9,700 reads as 9,700.00 GEU. Not converted — relabelled. The toggle
// executes no trade, charges no fee, causes no slippage and creates no
// taxable event, because nothing moves.
//
// ── The rule that keeps this honest ─────────────────────────────────────
//
// A GEU figure is MEANINGLESS WITHOUT THE CURRENCY IT WAS QUOTED IN. "2
// GEU" is ₹2 in Mumbai and $2 in New York, and the two are eighty-eight
// times apart. That is fine for a label on your own balance, where the
// currency is always yours. It is not fine anywhere a figure travels
// between two people.
//
// Which is why this module formats and nothing else. GEU appears on the
// dashboard, in history and on receipts — surfaces where a number is being
// READ, in one person's own currency. It appears nowhere money moves: Send
// Money, the payment confirmation and the amount a merchant is paid are all
// in real local currency on both sides, always.
//
// A transfer makes the reason obvious. Rohan sends ₹500 to John in New
// York, who receives $5.68. Labelled as GEU that reads "sent 500 GEU,
// received 5.68 GEU" — a unit changing magnitude in flight, which is an
// exchange rate, which is the one thing GEU is not.

// Which label the money is being read in. Two values, and `local` is the
// default for a reason: it is what somebody's bank, their statement and the
// shop they just paid all use, so it is the one that needs no explaining.
var GEU_LENS_LOCAL = "local";
var GEU_LENS_GEU = "geu";

// Remembered per device, not per account, and deliberately: the choice is
// about how a person likes to read numbers, which does not change when they
// sign in as somebody else on the same phone.
var GEU_LENS_KEY = "gloobal.displayUnit.v1";

// Every storage access is wrapped. localStorage throws outright in Safari's
// private mode and wherever site data is blocked, and a display preference
// is never worth taking the app down for.
function readGeuLens() {
  try {
    return window.localStorage.getItem(GEU_LENS_KEY) === GEU_LENS_GEU ? GEU_LENS_GEU : GEU_LENS_LOCAL;
  } catch (e) {
    return GEU_LENS_LOCAL;
  }
}

// ── ONE LENS, READ BY EVERY SCREEN ──────────────────────────────────────
//
// The toggle lives on the balance card, but the choice is about how this
// person reads money — so history, Coverage, receipts, My Assets, the
// notification cards and the earnings screens all have to answer to it too.
//
// Passing it down as a prop was the alternative, and it would have meant
// threading one value through a dozen components that have no interest in
// it, several of which are rendered from three different places. A screen
// that happened to be reached by a path nobody updated would then print
// rupees next to GEU on the same tap, which is the exact confusion this
// feature exists to prevent.
//
// So the preference is a tiny store instead: localStorage is the durable
// copy, this module keeps the live one, and anything that cares subscribes.
// useSyncExternalStore is React's own answer for state that lives outside
// React, and it is what keeps every screen on the same value in the same
// render rather than a frame apart.
var geuLensCurrent = null;
var geuLensListeners = new Set();

function geuLensSnapshot() {
  // Read through on first use so the store and storage cannot start out
  // disagreeing, then serve from memory. Returning a fresh value out of a
  // getSnapshot on every call is how useSyncExternalStore ends up in an
  // infinite loop, so this must stay a stable string.
  if (geuLensCurrent === null) geuLensCurrent = readGeuLens();
  return geuLensCurrent;
}

function geuLensSubscribe(listener) {
  geuLensListeners.add(listener);
  return function () {
    geuLensListeners.delete(listener);
  };
}

// The server has no idea what unit anybody is reading in, so the snapshot
// handed to a server render is simply the local one. Without this, any
// future SSR of a screen that reads the lens throws rather than rendering.
function geuLensServerSnapshot() {
  return GEU_LENS_LOCAL;
}

// The hook every screen uses. Takes nothing, because there is one lens.
function useGeuLens() {
  return useSyncExternalStore3(geuLensSubscribe, geuLensSnapshot, geuLensServerSnapshot);
}

function writeGeuLens(lens) {
  const next = lens === GEU_LENS_GEU ? GEU_LENS_GEU : GEU_LENS_LOCAL;
  // The in-memory copy moves first and the listeners fire regardless of
  // whether storage accepted it. A device with site data blocked still gets
  // a working toggle for the session; it just forgets by the next launch,
  // which is the right way round for a display preference.
  const changed = geuLensCurrent !== next;
  geuLensCurrent = next;
  try {
    window.localStorage.setItem(GEU_LENS_KEY, next);
  } catch (e) {
    // Losing the preference costs one tap next time.
  }
  if (changed) geuLensListeners.forEach((listener) => listener());
}

// ── The formatter ───────────────────────────────────────────────────────
//
// THE NUMBER IS NEVER TOUCHED. Not multiplied, not divided, not rounded a
// second time — the digits that come out are the digits that went in, with
// a different unit written after them. That identity is the whole claim
// this feature makes to a person ("switching changes the display, not your
// funds"), and the only way to keep it true is to never do arithmetic here.
//
// `fmtMoney(9700, "INR")` gives "9,700.00₹". In GEU the same figure is
// "9,700.00 GEU" — same digits, same decimal places, because the decimals
// belong to the amount rather than to the label.
//
// A currency with no minor unit keeps having none: ¥9,700 reads 9,700 GEU,
// not 9,700.00. decimalsFor is asked about the REAL currency, because that
// is the one the money is actually in.
function geuLensMoney(amount, currencyCode, lens) {
  if (lens !== GEU_LENS_GEU) return fmtMoney(amount, currencyCode);
  const places = typeof currencyDecimals === "function" ? currencyDecimals(currencyCode) : 2;
  const digits = new Intl.NumberFormat("en-US", {
    minimumFractionDigits: places,
    maximumFractionDigits: places
  }).format(Number(amount) || 0);
  return `${digits} ${COIN_TICKER}`;
}

// What the badge on the balance card says.
//
// In local units it names where the account lives — "Gloobal India" — which
// is the honest description of money sitting in Indian rupees under Indian
// rules.
//
// In GEU it says "Gloobal Hooman", and that is the point of the lens rather
// than decoration: the figure has stopped being a national number and
// become a human one. The money has not moved anywhere and is still exactly
// as sovereign as it was a second ago; only the frame around it changed.
function geuLensBadgeSuffix(lens, countryName) {
  if (lens === GEU_LENS_GEU) return " Hooman";
  return ` ${countryName || ""}`.trimEnd();
}

// The unit's own name, for anywhere that labels the figure rather than
// printing it — "Display currency: GEU" under the balance.
function geuLensUnitLabel(lens, currencyCode) {
  return lens === GEU_LENS_GEU ? COIN_TICKER : String(currencyCode || "").toUpperCase();
}

// How large the balance may be printed before it stops fitting on one line.
//
// ── Why a figure needs this at all ──────────────────────────────────────
//
// The balance was a flat 32px in the display face, which is right for
// "₹9,700.00" and wrong for "1,929,878.26 GEU (INR)". The second is
// twenty-two characters, and on a 360px phone it ran past the card and
// wrapped between the digits and the unit:
//
//   1,929,878.26
//   GEU (INR)
//
// which reads as two facts rather than one number. An amount and its unit
// are a single thing and belong on a single line.
//
// ── Why arithmetic and not a ladder of sizes ────────────────────────────
//
// The first fix was a ladder — 32, 29, 25, 22, 19, and a floor of 17. It
// handled every balance anyone had typed, and it had a cliff: past about a
// trillion the floor stopped shrinking while the string kept growing, and
// the overflow rule took over. On a money figure that is the worst
// available outcome. A balance rendered small is legible; a balance
// rendered "100,000,000,000,0…" is a DIFFERENT NUMBER, shown without a
// warning, in the one place on the screen a person trusts absolutely.
//
// A ladder also has to be re-tuned every time the card's width changes, and
// nothing makes it fail loudly when it is not. So this computes the size
// instead, from three things that can each be checked:
//
//   - how much the string has to print, weighted because the bracket is
//     rendered smaller and so costs less width per character;
//   - how wide one weighted character is per pixel of font size, measured
//     in the shipped display face rather than guessed;
//   - how much room the row actually has.
//
// ── Why the length and not the viewport ─────────────────────────────────
//
// A vw-based size shrinks the figure on a small phone whether or not it
// needed shrinking, and still overflows on a large one if the balance is
// long enough. What overflows is CONTENT, so content is what is measured.
//
// The GEU lens is why this bites now rather than a year ago. Rupees print
// as "₹9,700.00" — one glyph, no suffix. The same money in GEU is
// "9,700.00 GEU (INR)", eight characters longer before a single digit is
// added, and every thousand multiplies from there.

// Measured, not estimated: a span of the balance's weight and family, at a
// known size, divided by its weighted character count. Three samples agreed
// to within 3% (0.656, 0.657, 0.678), and the highest is the one used —
// overestimating width shrinks the text, which is safe, while
// underestimating it brings the wrap back.
var GEU_LENS_CHAR_RATIO = 0.68;

// The balance row on the narrowest phone this app is built for, after the
// card's padding and the eye button beside it. A 390px screen offers 276px;
// this is the 320px case, so the common phone has margin rather than the
// rare one having a defect.
var GEU_LENS_FIGURE_ROOM = 258;

// 32 is the design size and nothing is ever printed larger. 13 is the floor
// for the BALANCE, and it is a floor rather than a continuation because below
// it the figure stops being the loudest thing on the card, which is a
// different kind of broken. It holds a twenty-nine character balance —
// "100,000,000,000,000.00 GEU (INR)" and more — so reaching it means the card
// is the wrong shape for the money in it, not that the rule gave up.
//
// A caller may pass its own floor. The week's two figures under the balance
// do: they are secondary, they share one row between them, and 11px keeps
// them side by side where 13 would push them onto separate lines. A smaller
// floor is right exactly where the figure is not the point of the card.
var GEU_LENS_FIGURE_MAX = 32;
var GEU_LENS_FIGURE_MIN = 13;

function geuLensFigureFontSize(figure, bracket, availablePx, floorPx) {
  // 0.45 is the bracket's 13px against the figure's 32px, rounded toward
  // caution for the same reason the ratio above is.
  const weighted = String(figure || "").length + String(bracket || "").length * 0.45;
  if (!(weighted > 0)) return GEU_LENS_FIGURE_MAX;

  // A measured width when the caller has one, the narrow-phone constant
  // when it does not. Number(null) is 0 and 0 is finite, so this asks
  // whether the number is POSITIVE rather than whether it is present.
  const room = Number(availablePx) > 0 ? Number(availablePx) : GEU_LENS_FIGURE_ROOM;

  // Same positive test as the width: Number(null) is 0, and a floor of 0
  // would let a figure shrink to nothing rather than fall back to the
  // default.
  const floor = Number(floorPx) > 0 ? Number(floorPx) : GEU_LENS_FIGURE_MIN;

  const ideal = Math.floor(room / (weighted * GEU_LENS_CHAR_RATIO));
  return Math.max(floor, Math.min(GEU_LENS_FIGURE_MAX, ideal));
}

// ── THE RULE: ONLY YOUR OWN MONEY IS RELABELLED ─────────────────────────
//
// 1 GEU is one unit of the VIEWER'S tender. That is what makes the lens a
// relabelling rather than a conversion — and it is also what stops it being
// applied to every figure on the screen.
//
// A history row for a cross-border payment holds two amounts: what left the
// payer in rupees and what reached the payee in dollars. Both are real, and
// they are not the same unit. Writing GEU after both would put two
// different quantities under one name on one row, which is precisely the
// misreading the whole feature exists to prevent — somebody would compare
// "8000 GEU" with "98 GEU" and conclude the money shrank.
//
// So the question asked here is not "is the lens on" but "is this figure in
// the reader's own money". Theirs gets the new name. Everyone else's keeps
// its own symbol, lens or no lens, and the row reads honestly as what it
// is: your side in your unit, their side in theirs.
//
// The founder's coffee shop is the same rule from the other end. He stands
// in New York, is asked for 2, and his phone charges him ₹176 — because the
// 2 he was quoted is the shop's own unit, and what he pays is his. Two
// numbers, two tenders, one payment, and neither of them is wrong.

// Two ISO codes naming the same currency. Case-insensitive because a code
// arrives from a dozen places — a row, a prop, a server field — and "inr"
// and "INR" being treated as different currencies would silently stop a
// figure being relabelled with no visible error anywhere.
function geuLensSameCurrency(a, b) {
  const left = String(a || "").trim().toUpperCase();
  const right = String(b || "").trim().toUpperCase();
  // Both must be real codes. Empty equals empty is true and would relabel
  // everything the moment a currency went missing, which is the failure
  // this guard exists for rather than a style preference.
  if (!/^[A-Z]{3}$/.test(left) || !/^[A-Z]{3}$/.test(right)) return false;
  return left === right;
}

// The formatter every screen outside the balance card should call.
//
// `ownCurrency` is the viewer's own tender. When it is not known — and it is
// genuinely unknown on some screens before an account loads — nothing is
// relabelled, because the alternative is calling somebody else's dollars GEU
// on the strength of a guess.
function geuLensOwnMoney(amount, currencyCode, lens, ownCurrency) {
  if (lens !== GEU_LENS_GEU) return fmtMoney(amount, currencyCode);
  if (!geuLensSameCurrency(currencyCode, ownCurrency)) return fmtMoney(amount, currencyCode);
  return geuLensMoney(amount, currencyCode, lens);
}

// Whether a given figure WOULD be relabelled. Screens that draw their own
// unit label beside a number — the Coverage tiles, the earnings headline —
// ask this rather than repeating the rule and drifting from it.
function geuLensAppliesTo(currencyCode, lens, ownCurrency) {
  return lens === GEU_LENS_GEU && geuLensSameCurrency(currencyCode, ownCurrency);
}

// ── THE BAR ─────────────────────────────────────────────────────────────
//
//     −959.07₹ │ GEU          and, with the toggle flipped,
//     −959.07 GEU │ ₹
//
// Every amount in the app that carries a currency carries this, and the
// rule is one sentence: THE BAR NAMES THE FIGURE'S OTHER NAME.
//
// For the viewer's own money that other name is the unit they are not
// currently reading in, so the two halves swap when the toggle does. The
// figure never moves — ₹959.07 and 959.07 GEU are the same money under the
// same digits — and showing both names at once is what makes that visible
// instead of something a person has to be told.
//
// ── Why it replaced the bracket ─────────────────────────────────────────
//
// The balance card said "(INR)" under its figure and nothing else in the
// app said anything, so the lens was explained in exactly one place and
// implied in nine. A row reading "−959.07₹" after the toggle had been
// flipped looked like the toggle had missed it.
//
// A bracket is also the wrong punctuation for this. Brackets hold an aside
// — something you could skip — and the second unit is not an aside, it is
// the other half of the same fact. A rule between two names reads as two
// names for one thing, which is what it is.
//
// ── Why somebody else's money gets a bar too ────────────────────────────
//
// On a foreign figure there is no second unit to name: the lens does not
// touch it (see the rule above), so the bar names the currency itself —
// 98.00€ │ EUR. That is not the same job, and it is worth being plain that
// it is a deliberate second meaning rather than an oversight.
//
// It earns its place because a symbol is not an identifier. ₹ is the rupee
// of five countries, $ belongs to more than twenty, and kr to four — on a
// cross-border receipt the symbol alone does not say whose money the other
// side was in. The code does.
//
// Which is also why a currency whose symbol IS its code gets no bar:
// "98.00 CHF │ CHF" names the franc twice and tells nobody anything.
var GEU_LENS_BAR = "\u2502";

// The gap between the balance's figure and its bar, where the two are drawn
// as SEPARATE SPANS so the bar can be smaller and quieter than the number.
// Everywhere else the bar sits inside one string and the space around it is a
// plain space, which costs nothing to account for.
//
// Shared with the sizer because it is width the figure does not get, and the
// two guessing separately is how a hundred-trillion balance came out 259px
// wide in a 258px row. One pixel over, and found by measuring every figure
// against its room rather than by looking at a screenshot of a plausible
// balance — which is the mistake that made the toggle take three attempts.
var GEU_LENS_BAR_GAP = 7;

// The name that goes after the bar, or "" when the figure already carries
// it. Separate from the formatter below because the Coverage tiles and the
// earnings headline print their unit as their own element rather than
// inside a string, and they must get the name from here rather than
// reimplement the choice.
function geuLensBarUnit(currencyCode, lens, ownCurrency) {
  // UPPER-CASED BEFORE THE SYMBOL IS LOOKED UP, and this is not tidiness.
  //
  // geuLensSameCurrency is deliberately case-insensitive, because a code
  // arrives here from a row, a prop and a server field and "inr" must not be
  // a different currency from "INR". So a lowercase code reaches this line
  // having been accepted as the viewer's own — and CURRENCY_SYMBOL has no
  // "inr" key, so currencySuffix falls back to printing the code back as it
  // was given. The bar then read "500.00 GEU │ inr" instead of naming the
  // rupee: the figure relabelled correctly and its other name came out as
  // the wrong string, with no error anywhere.
  const code = String(currencyCode || "").trim().toUpperCase();
  if (!/^[A-Z]{3}$/.test(code)) return "";

  // ── YOUR MONEY IS NAMED BY ITS SYMBOL, THEIRS BY ITS CODE ─────────────
  //
  // Both are the SAME JOB — say which real money this figure is in — and the
  // two answers are different because the question behind them is.
  //
  // On your own figure the currency is never in doubt; it is the one your
  // account is in, and you have seen that glyph on every price in your life.
  // ₹ is the shortest true answer.
  //
  // On somebody else's it is exactly what IS in doubt. A symbol is not an
  // identifier: ₹ is the rupee of five countries, $ belongs to more than
  // twenty and kr to four, so "98.00 GEU │ €" would still leave a reader
  // guessing which euro-ish money the other side was in. EUR does not.
  if (geuLensSameCurrency(code, ownCurrency)) {
    // currencySuffix gives the glyph where there is one ("₹") and the code
    // where there is not ("CHF"), trimmed — it stores several symbols with a
    // trailing space for prefix use.
    return String(typeof currencySuffix === "function" ? currencySuffix(code) : code).trim();
  }
  return code;
}

// ── GEU GOES ON EVERY FIGURE, AND NEVER TRAVELS ALONE ───────────────────
//
//   toggle off      8,000.00₹ │ GEU          98.00€ │ EUR
//   toggle on       8,000.00 GEU │ ₹         98.00 GEU │ EUR
//
// ── What this replaced, and why the replacement is not looser ───────────
//
// GEU used to be a unit with a MAGNITUDE — 1 GEU = 1 unit of the viewer's
// own tender — which meant it could only ever be written on the viewer's own
// money. Writing it on €98 would have been false: for an Indian reader 98
// GEU was ₹98, and €98 is not. So the old rule was "rename only your own",
// and a foreign figure kept its symbol untouched.
//
// The founder's model is different, and it is the one in force:
//
//     "no not type GEU anywhere independently … GEU | INR | rupee symbol
//      are same things … shop is asking 2 GEU | USD, I pay them 176 GEU |
//      INR. THEY ARE NOT APART, THEY ARE TRUE."
//
// GEU is the name of the SYSTEM, and the currency after the bar says which
// money the figure is in. "2 GEU │ USD" is two dollars. "176 GEU │ INR" is a
// hundred and seventy-six rupees. Both are true, neither is ambiguous, and
// they are not two readings of one quantity — they are two quantities, each
// fully named.
//
// THE SAFETY PROPERTY SURVIVES, IN A DIFFERENT SHAPE. The thing that made
// "2 GEU" dangerous was never the word GEU; it was GEU with nothing beside
// it, which a reader completes from their own country. So the invariant
// moved from
//
//     GEU never appears on somebody else's money
//
// to the stricter and simpler
//
//     GEU never appears without the currency it is in
//
// which is the rule this function exists to keep. It is stricter because it
// now binds the viewer's OWN figures too: under the old rule "9,700.00 GEU"
// stood alone on the balance card and was fine only because the card
// happened to be about one account. Nothing in the format said so.
//
// Where money MOVES is unchanged and is not this function's business: Send
// Money, the amount field and a payment request are all in plain real
// currency on both sides, with no GEU anywhere — the founder confirmed both.
// A quote that travels between two people cannot carry a unit whose meaning
// depends on who is reading it, however well it is labelled.
// ── THE NAME YOU READ IN IS LIT, AFTER THE BAR (0228) ───────────────────
//
// Every figure carries both its names: the money it is in, and GEU. The
// other name sits on the number, dimmed; the bar; then the name the lens
// picked, bright, so the eye lands on it (GeuFigure). 0224 put the picked
// name first; the founder asked for it second (4 Nov).
//
//     local lens   1,000.00 GEU │ ₹       40.00 GEU │ USD
//     geu lens     1,000.00₹ │ GEU        40.00 USD │ GEU
//
// Your own money by its sign, anyone else's by its code. GEU is on every
// figure, yours or not (founder, 3 Nov: "geu is missing in a few places") —
// and still never WITHOUT the currency it is in, which is the safety rule
// above.
function geuLensNames(currencyCode, lens, ownCurrency) {
  const unit = geuLensBarUnit(currencyCode, lens, ownCurrency);
  if (!unit) return null;
  // lead = on the number, dimmed; trail = after the bar, the one picked.
  return lens === GEU_LENS_GEU ? { lead: unit, trail: COIN_TICKER } : { lead: COIN_TICKER, trail: unit };
}
function geuLensDigits(amount, currencyCode) {
  const places = typeof currencyDecimals === "function" ? currencyDecimals(currencyCode) : 2;
  return new Intl.NumberFormat("en-US", { minimumFractionDigits: places, maximumFractionDigits: places }).format(Number(amount) || 0);
}
// A sign sits on the number ("1,000₹"); a word stands apart ("40.00 USD").
function geuLensGlue(name) { return /[A-Za-z]/.test(String(name || "")) ? " " : ""; }

function geuLensBarMoney(amount, currencyCode, lens, ownCurrency) {
  const names = geuLensNames(currencyCode, lens, ownCurrency);
  // No usable currency — a figure that is not money in any tender, or a code
  // that arrived malformed. GEU would have nothing to stand beside, so it is
  // not written: the rule above is the whole point.
  if (!names) return fmtMoney(amount, currencyCode);
  return `${geuLensDigits(amount, currencyCode)}${geuLensGlue(names.lead)}${names.lead} ${GEU_LENS_BAR} ${names.trail}`;
}

// ── THE UNIT YOU CHOSE IS THE BIGGER ONE ────────────────────────────────
//
//     toggle on       8,000.00 GEU │ ₹        GEU full size, ₹ at 75%
//     toggle off      8,000.00₹ │ GEU         ₹ full size, GEU at 75%
//
// The founder's words: "during toggle flip INR big GEU small, like that, so
// we show them what they chose is bigger than the other".
//
// Which makes the size do a job no label can. Both names are always on the
// line — that is the rule this module exists to keep — so the only thing
// left to say is WHICH ONE YOU ARE READING IN, and a person should be able
// to answer that without reading either word. Weight of type answers it at a
// glance, and it answers it the same way on a balance card, a history row
// and a receipt, because it is a ratio rather than a size.
//
// 0.75 and not smaller. The balance card's old bracket sat at 0.42, which
// works on a 32px figure and gives 6px on a 14px history row — small enough
// to be decoration rather than information, on the half of the line that
// says which currency the money is in.
