      position: "absolute",
      top: GEU_LENS_PILL_PAD,
      left: flagLeft,
      width: GEU_LENS_DISC,
      height: GEU_LENS_DISC,
      borderRadius: "50%",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transition: slide
