      // sitting next to.
      width: 32,
      height: 32,
      borderRadius: "50%",
      flexShrink: 0,
      background: markColour,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      boxShadow: "0 6px 16px -11px rgba(20,10,50,0.8)"
