        const el = nodesRef.current[i];
        if (!el) continue;
        const b = bodies[i];
        el.style.transform = `translate(${(b.x - b.w / 2).toFixed(1)}px, ${(b.y - b.h / 2).toFixed(1)}px) rotate(${b.rot}deg)`;
