  const bigRows = APP_MAP_BIG.map((big) => ({ big, entry: unlocked.find((e) => e.key === big.key) })).filter((r) => r.entry);
  const HereIcon = here ? APP_MAP_ICONS[here.key] || MapFallbackIcon : MapHomeIcon;

