      timers.push(setTimeout(() => setPhase("fading"), holdLogoMs + FLIP_MS + HOLD_SYMBOL_MS));
      timers.push(setTimeout(() => onFinish?.(), holdLogoMs + FLIP_MS + HOLD_SYMBOL_MS + FADE_MS));
